  <script>
    const storyVideoModal = document.getElementById('videoModal');
    const storyIframeWrapper = document.getElementById('iframeWrapper');

    function openVideoModal(youtubeId) {
      if (!storyVideoModal || !storyIframeWrapper) return;
      storyIframeWrapper.innerHTML = `
        <iframe src="https://www.youtube.com/embed/${youtubeId}?autoplay=1&rel=0" 
                allow="accelerometer; autoplay; clipboard-write; encrypted-media; gyroscope; picture-in-picture" 
                allowfullscreen style="position: absolute; top: 0; left: 0; width: 100%; height: 100%; border: none;"></iframe>
      `;
      storyVideoModal.style.display = 'flex';
      storyVideoModal.offsetHeight;
      storyVideoModal.style.opacity = '1';
      document.body.style.overflow = 'hidden';
    }

    function closeVideoModal(event) {
      if (!storyVideoModal || !storyIframeWrapper) return;
      storyVideoModal.style.opacity = '0';
      document.body.style.overflow = '';
      setTimeout(() => {
        storyIframeWrapper.innerHTML = '';
        storyVideoModal.style.display = 'none';
      }, 300);
    }

    document.addEventListener('keydown', (e) => {
      if (e.key === 'Escape' && storyVideoModal && storyVideoModal.style.display === 'flex') {
        closeVideoModal();
      }
    });
  </script>

